answers_by_section={
'summary':[('FDA banana non-detect bounds coexist with quantified lead, nickel and chromium in a Korean fresh-fruit survey and cadmium/chromium in a dried Ethiopian pooled edible fraction.',[F,L,M]),('Prioritize edible-material sampling and analytical sensitivity; no banana cultivar or origin advantage has been established. Same-study fruit alternatives trade off Pb/Ni or Cd/Cr rather than supplying one overall lower choice.',[L,M]),('Origin-linked banana lots, cultivar/production-system comparisons, derivative measurements, paired intervention effects and current primary-law applicability remain unfinished.',[])],
'identity':[content['identity'][0],content['identity'][1],('No concentration transfers between fresh pulp, dried analytical flesh, peel, commercial powder or infant puree without justified matrix, moisture, yield and recipe reconciliation.',[])],
'occurrence':[('FDA investigated tAs, Cd, Cr, Pb, tHg, Ni and U; Lee investigated elemental As, Ba, Cd, Cr, Ni, Pb and Sb; Mekonnen measured Pb, Cd, Cr and Cu. None measured banana iAs, MeHg or Cr(VI).',[F,L,M]),('The structured occurrence record retains 15 source summaries. FDA has 27 composites, six Ni detections at 43–140 µg/kg and one tAs detection at 3.2 µg/kg. Lee has 15 banana samples; Mekonnen describes one pooled banana material with triplicate analysis.',[F,L,M]),('Aluminium, tin, chemical species and remaining candidate studies have not been fully assessed. No completed-search absence claim is made; other linked sources remain in source-review.json.',[])],
'pathways':[content['pathways'][0],('Agricultural/environmental pathways are discussed in the papers, but banana equipment, packaging and handling contributions were not experimentally separated. They remain hypotheses rather than measured transfer fractions.',[L,M]),content['pathways'][1]],
'variation':[content['variation'][2],('FDA composites, individual Korean fruit samples and pooled Ethiopian material address different variation scales. No same-banana supplier, organic-production or within-lot variability estimate is derived from these aggregate findings.',[F,L,M]),content['variation'][0]],
'processing':[content['processing'][0],content['processing'][1],('No banana metal mass balance, paired moisture/yield endpoints, dilution experiment or species/availability transformation was verified. Analytical drying cannot be interpreted as measured metal removal.',[])],
'controls':[content['controls'][0],('No monitored-versus-unmonitored banana comparator, validated removal effect, control timing or residual concentration was established. The source monitoring recommendation is retained as context with null effect endpoints.',[M]),('Commercial monitoring efficacy, cost, validated sampling frequency and process verification remain unresolved. The source recommendation is not a tested manufacturing control program.',[])],
'tradeoffs':[('No paired banana intervention or by-product metal balance was admitted. The observed Pb/Ni and Cd/Cr fruit-group trade-offs are occurrence comparisons, not treatment-induced increases.',[L,M]),('Intervention effects on nutrition, yield, sensory quality, stability and waste were not evaluated by the admitted banana comparisons. They remain unassessed rather than assumed harmless.',[]),('Detection sensitivity, composite averaging and unmatched material bases can mislead a sourcing decision. Intervention cost and operational feasibility are unquantified; no benefit-cost estimate is assigned.',[F,L,M])],
'testing':[content['testing'][0],content['testing'][2],content['testing'][1]],
'procurement':[content['procurement'][1],('Representative edible-material measurement can inform a proposed procurement decision. No current legal acceptance threshold, testing frequency or validated banana-lot specification has been adopted here.',[]),('A change in banana form, origin/lot traceability, moisture basis or reporting limit should reopen comparability. This is a proposed review trigger based on source-scope differences, not an experimentally validated schedule.',[F,L,M])],
'product':[content['product'][1],content['product'][0],('Infant-food concentration, actual consumption, absorbed dose, personal risk and product compliance need separate finished-food measurements and applicable exposure/legal assessment. No raw-fruit result supplies those conclusions.',[])],
'assessment':[content['assessment'][1],content['assessment'][0],('This 22 October 2026 candidate replaces unsupported legacy near-zero and processing claims with primary-verified source findings. Remaining source extraction, origin/cultivar comparisons, derivative/intervention assessment and current-law verification stay unresolved; no human peer review or systematic-review completion is claimed.',[])]}
